def transform(grid):
    """Tile the occupied cells with 2x2 squares and 2x2 L-triominoes.

    Squares are recolored 1. L pieces are colored by the missing corner:
    top-left=2, bottom-left=3, top-right=4, bottom-right=5.
    """
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= occupied:
                pieces.append((box, 1))
            for missing, color in [((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4), ((r + 1, c + 1), 5)]:
                shape = box - {missing}
                if shape <= occupied:
                    pieces.append((shape, color))

    by_cell = {cell: [] for cell in occupied}
    for shape, color in pieces:
        for cell in shape:
            by_cell[cell].append((shape, color))

    @lru_cache(None)
    def tile(remaining):
        if not remaining:
            return ()
        rem = set(remaining)
        cell = min(rem)
        for shape, color in by_cell[cell]:
            if shape <= rem:
                rest = tile(tuple(sorted(rem - shape)))
                if rest is not None:
                    return ((shape, color),) + rest
        return None

    solution = tile(tuple(sorted(occupied)))
    if solution is None:
        raise ValueError("Occupied cells cannot be tiled by the demonstrated pieces")
    out = [[0] * w for _ in range(h)]
    for shape, color in solution:
        for r, c in shape:
            out[r][c] = color
    return out
